#!/usr/bin/env node
// Benana minecraft MCP server (stdio, newline-delimited JSON-RPC). Owner: Track A.
// Gives a Claude Code playtester control of the in-game bot through Benana's local control API,
// and records the verdict file the studio pipeline reads (docs/hackathon/CONTRACTS.md).
// Env: BENANA_GAME_URL, BENANA_VERDICT_FILE, BENANA_TEST_PLAN, BENANA_RUN_ID.
const fs = require('node:fs');
const path = require('node:path');
const readline = require('node:readline');

const gameUrl = process.env.BENANA_GAME_URL;
const verdictFile = process.env.BENANA_VERDICT_FILE;
const runId = process.env.BENANA_RUN_ID || 'manual';
const startedAt = Date.now();

const obj = (properties, required = []) => ({ type: 'object', properties, required });
const entityId = { type: 'number', description: 'Entity id from nearby_entities' };
const position = { type: 'array', items: { type: 'number' }, minItems: 3, maxItems: 3, description: '[x, y, z]' };
const trackTicks = { type: 'number', description: 'Record the target for this many ticks right after the action (20 ticks = 1s). Use it whenever the expected effect is movement.' };

const tools = [
  { name: 'game_setup', description: 'Run server console commands as the bot (no leading slash). `@bot` is the bot; ^ and ~ coordinates are relative to it. Use for the test plan setup: give items, summon mobs, set time.', inputSchema: obj({ commands: { type: 'array', items: { type: 'string' } } }, ['commands']) },
  { name: 'bot_state', description: 'Bot position, health, held item and inventory.', inputSchema: obj({}) },
  { name: 'nearby_entities', description: 'Entities near the bot with id, type, position, velocity and distance, nearest first.', inputSchema: obj({ radius: { type: 'number' } }) },
  { name: 'equip', description: 'Hold an inventory item, e.g. golden_sword.', inputSchema: obj({ item: { type: 'string' } }, ['item']) },
  { name: 'look_at', description: 'Aim at an entity or position.', inputSchema: obj({ entityId, position }) },
  { name: 'move_to', description: 'Walk to an entity or position.', inputSchema: obj({ entityId, position, range: { type: 'number' } }) },
  { name: 'attack', description: 'Left-click (hit) an entity with the held item. Walks into reach first if needed.', inputSchema: obj({ entityId, trackTicks }, ['entityId']) },
  { name: 'attack_sequence', description: 'Hit several entities back to back, intervalTicks apart (default 4), in ONE call, and track each. Use for cooldowns and combos; separate attack calls are seconds apart.', inputSchema: obj({ entityIds: { type: 'array', items: { type: 'number' } }, intervalTicks: { type: 'number' }, trackTicks }, ['entityIds']) },
  { name: 'use_item', description: 'Right-click with the held item, on an entity if entityId is given.', inputSchema: obj({ entityId, trackTicks }) },
  { name: 'track_entity', description: 'Sample an entity every tick: position, velocity, and position delta, plus maxUpwardVelocity and maxHeightGain.', inputSchema: obj({ entityId, ticks: { type: 'number' } }, ['entityId']) },
  { name: 'wait_ticks', description: 'Let the game run (20 ticks = 1 second).', inputSchema: obj({ ticks: { type: 'number' } }, ['ticks']) },
  { name: 'chat', description: 'Say something or run a player command like /launch.', inputSchema: obj({ message: { type: 'string' } }, ['message']) },
  { name: 'read_chat', description: 'Chat messages the bot has seen, optionally since a unix ms timestamp.', inputSchema: obj({ sinceMs: { type: 'number' } }) },
  { name: 'server_log', description: 'Server console lines since a unix ms timestamp (default: since this playtest started). level "error" shows plugin exceptions.', inputSchema: obj({ sinceMs: { type: 'number' }, level: { type: 'string', enum: ['error', 'warn'] } }) },
  {
    name: 'report_check',
    description: 'Record the result of one test plan check. Call once per check id.',
    inputSchema: obj({
      id: { type: 'string' },
      status: { type: 'string', enum: ['pass', 'fail', 'blocked'] },
      expected: { type: 'string' },
      observed: { type: 'string', description: 'What actually happened, with numbers' },
      evidence: { type: 'object', description: 'Measurements, samples, or log lines supporting the result' },
      suspectedCause: { type: 'string', description: 'For failures: your best guess at the plugin bug' },
    }, ['id', 'status', 'expected', 'observed']),
  },
  { name: 'finish', description: 'Finalize the playtest after every check is reported.', inputSchema: obj({ summary: { type: 'string' } }, ['summary']) },
];

async function game(tool, args) {
  if (!gameUrl) throw new Error('BENANA_GAME_URL is not set; start the game in Benana first.');
  const res = await fetch(`${gameUrl}/tool/${tool}`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(args || {}) });
  const out = await res.json();
  if (!out.ok) throw new Error(out.error);
  return out.result;
}

function readVerdict() {
  try { return JSON.parse(fs.readFileSync(verdictFile, 'utf8')); }
  catch { return { version: 1, runId, finished: false, passed: false, summary: '', checks: [], serverErrors: [] }; }
}

function writeVerdict(v) {
  if (!verdictFile) throw new Error('BENANA_VERDICT_FILE is not set.');
  fs.mkdirSync(path.dirname(verdictFile), { recursive: true });
  fs.writeFileSync(verdictFile, JSON.stringify(v, null, 2));
}

// Group console error lines and their stack frames into one entry per exception.
function groupErrors(lines) {
  const out = [];
  for (const l of lines) {
    const frame = /^\s*(at |Caused by|\.\.\. \d+ more)/.test(l.line);
    if (frame && out.length) out[out.length - 1].stack += `${l.line}\n`;
    else out.push({ at: l.at, message: l.line, stack: '' });
  }
  return out;
}

async function call(name, a) {
  if (name === 'server_log') return game('server_log', { sinceMs: a.sinceMs ?? startedAt, level: a.level });
  if (name === 'report_check') {
    const v = readVerdict();
    const check = { id: a.id, status: a.status, expected: a.expected, observed: a.observed, evidence: a.evidence || {}, ...(a.suspectedCause ? { suspectedCause: a.suspectedCause } : {}) };
    v.checks = [...v.checks.filter((c) => c.id !== a.id), check];
    writeVerdict(v);
    return { recorded: a.id, checks: v.checks.length };
  }
  if (name === 'finish') {
    const v = readVerdict();
    v.serverErrors = groupErrors(await game('server_log', { sinceMs: startedAt, level: 'error' }));
    v.finished = true;
    v.summary = a.summary;
    v.passed = v.checks.length > 0 && v.checks.every((c) => c.status === 'pass') && v.serverErrors.length === 0;
    writeVerdict(v);
    return { passed: v.passed, checks: v.checks.map((c) => `${c.id}: ${c.status}`), serverErrors: v.serverErrors.length };
  }
  return game(name, a);
}

const send = (msg) => process.stdout.write(`${JSON.stringify({ jsonrpc: '2.0', ...msg })}\n`);

readline.createInterface({ input: process.stdin }).on('line', async (line) => {
  let req;
  try { req = JSON.parse(line); } catch { return; }
  const { id, method, params = {} } = req;
  if (id === undefined) return; // notification
  try {
    if (method === 'initialize') {
      send({ id, result: { protocolVersion: params.protocolVersion || '2025-06-18', capabilities: { tools: {} }, serverInfo: { name: 'benana-minecraft', version: '0.1.0' } } });
    } else if (method === 'tools/list') {
      send({ id, result: { tools } });
    } else if (method === 'tools/call') {
      const out = await call(params.name, params.arguments || {});
      send({ id, result: { content: [{ type: 'text', text: JSON.stringify(out, null, 2) }] } });
    } else if (method === 'ping') {
      send({ id, result: {} });
    } else {
      send({ id, error: { code: -32601, message: `Method not found: ${method}` } });
    }
  } catch (e) {
    send({ id, result: { isError: true, content: [{ type: 'text', text: e.message }] } });
  }
});

// Game runtime: local Paper server, the Mineflayer test bot, and the in-app viewer.
// Owner: Track A. Interface: docs/hackathon/CONTRACTS.md.
// BENANA_GAME_MOCK=1 returns canned results so the studio pipeline can be built before the real runtime lands.
//
// Process layout: Electron main runs the Paper server (server.cjs) and a local HTTP control API that the
// `minecraft` MCP server calls. The bot and viewer run in host.cjs under system Node, because Mineflayer
// needs Node 22+ and Electron 33 ships Node 20.
const fs = require('node:fs');
const http = require('node:http');
const path = require('node:path');
const { spawnSync } = require('node:child_process');
const { appRoot } = require('../env.cjs');
const { resolveExecutable, spawnExecutable, terminateProcessTree } = require('../processes.cjs');
const { Server, VERSION, PORT } = require('./server.cjs');

const BOT = 'BenanaBot';
// The bot is kept near this spot so it stays inside the viewer's fixed camera orbit.
const ARENA = [0.5, 65, 0.5];
const VIEWER_PORT = 3007;
const HOST = path.join(__dirname, 'host.cjs');
const MCP = path.join(appRoot, 'electron', 'mcp-minecraft.cjs');
const mock = () => process.env.BENANA_GAME_MOCK === '1';

const BOT_TOOLS = new Set(['bot_state', 'nearby_entities', 'equip', 'look_at', 'move_to', 'attack', 'attack_sequence', 'use_item', 'track_entity', 'wait_ticks', 'chat', 'read_chat']);
const TOOLS = ['game_setup', ...BOT_TOOLS, 'server_log', 'report_check', 'finish'];
const playtesterTools = TOOLS.map((t) => `mcp__minecraft__${t}`);

let state = { server: 'stopped', bot: 'offline', viewerUrl: null, controlUrl: null, version: VERSION, mock: mock(), error: null };
let emitter = () => {};

function setState(patch) {
  state = { ...state, ...patch, mock: mock() };
  emitter('game:status', state);
  return state;
}

const status = () => ({ ...state, mock: mock() });

const server = new Server();
let host = null;
let control = null;
const pending = new Map();
let seq = 0;

function systemNode() {
  const out = spawnSync(resolveExecutable('node'), ['-p', 'process.versions.node'], { encoding: 'utf8', windowsHide: true });
  const major = Number(String(out.stdout || '').trim().split('.')[0]);
  if (!major) throw new Error('System Node was not found on PATH. The game bot needs Node 22 or newer.');
  if (major < 22) throw new Error(`The game bot needs Node 22 or newer on PATH (found ${out.stdout.trim()}).`);
}

function startHost() {
  return new Promise((resolve, reject) => {
    const child = spawnExecutable('node', [HOST], {
      cwd: appRoot,
      stdio: ['ignore', 'pipe', 'pipe', 'ipc'],
      env: {
        ...process.env, MC_PORT: String(PORT), MC_VERSION: VERSION, BOT_NAME: BOT,
        VIEWER_PORT: String(VIEWER_PORT), VIEWER_FIRST_PERSON: process.env.BENANA_VIEW === 'first' ? '1' : '0',
      },
    });
    host = child;
    setState({ bot: 'connecting' });
    const timer = setTimeout(() => reject(new Error('The bot did not join within 60 seconds.')), 60000);
    const forward = (d) => String(d).split(/\r?\n/).filter(Boolean)
      .forEach((line) => emitter('game:log', { line: `[bot] ${line}`, level: 'info', at: Date.now() }));
    child.stdout.on('data', forward);
    child.stderr.on('data', forward);
    child.on('message', (msg) => {
      if (msg.id != null && pending.has(msg.id)) {
        const p = pending.get(msg.id);
        pending.delete(msg.id);
        return msg.ok ? p.resolve(msg.result) : p.reject(new Error(msg.error));
      }
      if (msg.event === 'status') {
        setState({ bot: msg.bot, ...(msg.error ? { error: msg.error } : {}) });
        if (msg.bot === 'online') { clearTimeout(timer); resolve(); }
      }
      if (msg.event === 'chat') emitter('game:log', { line: `[chat] ${msg.text}`, level: 'info', at: Date.now() });
    });
    child.on('exit', (code) => {
      clearTimeout(timer);
      if (host === child) { host = null; setState({ bot: 'offline', viewerUrl: null }); }
      for (const p of pending.values()) p.reject(new Error('The bot disconnected.'));
      pending.clear();
      reject(new Error(`The bot process exited (code ${code}).`));
    });
  });
}

async function stopHost() {
  const child = host;
  if (!child) return;
  host = null;
  const exited = new Promise((res) => child.once('exit', res));
  try { child.disconnect(); } catch {}
  const timer = setTimeout(() => terminateProcessTree(child), 3000);
  await exited;
  clearTimeout(timer);
}

function botCall(tool, args) {
  if (!host) return Promise.reject(new Error('The bot is not connected.'));
  const id = ++seq;
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => { pending.delete(id); reject(new Error(`${tool} timed out`)); }, 60000);
    pending.set(id, {
      resolve: (v) => { clearTimeout(timer); resolve(v); },
      reject: (e) => { clearTimeout(timer); reject(e); },
    });
    host.send({ id, tool, args });
  });
}

async function prepareWorld() {
  for (const cmd of ['gamerule doDaylightCycle false', 'gamerule doWeatherCycle false', 'gamerule doMobSpawning false', 'gamerule sendCommandFeedback false', 'time set day', 'weather clear'])
    await server.command(cmd);
}

async function prepareBot() {
  for (const cmd of [`tp ${BOT} ${ARENA.join(' ')} 0 0`, `gamemode survival ${BOT}`, `effect give ${BOT} resistance infinite 4 true`, `effect give ${BOT} saturation infinite 0 true`, `clear ${BOT}`])
    await server.command(cmd);
}

// Tools shared by the MCP server (over HTTP) and the in-app demo controls.
async function runTool(tool, args = {}) {
  if (BOT_TOOLS.has(tool)) return botCall(tool, args);
  if (tool === 'game_setup') {
    const out = [];
    const { position } = await botCall('bot_state');
    if (Math.hypot(position[0] - ARENA[0], position[2] - ARENA[2]) > 8) {
      await server.command(`tp ${BOT} ${ARENA.join(' ')} 0 0`);
      await botCall('wait_ticks', { ticks: 5 });
      out.push({ command: 'tp back to the arena center', output: 'Benana keeps the bot in camera view' });
    }
    for (const raw of args.commands || []) {
      const cmd = String(raw).replace(/^\//, '').replaceAll('@bot', BOT);
      out.push({ command: cmd, output: await server.command(`execute as ${BOT} at ${BOT} run ${cmd}`) });
    }
    return out;
  }
  if (tool === 'server_log') return server.logSince(Number(args.sinceMs) || 0, args.level).slice(-200);
  throw new Error(`Unknown game tool ${tool}`);
}

function startControl() {
  if (control) return Promise.resolve();
  return new Promise((resolve) => {
    control = http.createServer((req, res) => {
      const match = req.method === 'POST' && req.url.match(/^\/tool\/(\w+)$/);
      if (!match) { res.writeHead(404).end(); return; }
      let body = '';
      req.on('data', (d) => { body += d; });
      req.on('end', async () => {
        let args = {};
        try { args = body ? JSON.parse(body) : {}; } catch {}
        const reply = (payload) => res.writeHead(200, { 'Content-Type': 'application/json' }).end(JSON.stringify(payload));
        const action = { tool: match[1], args, at: Date.now() };
        emitter('game:action', action);
        try {
          const result = await runTool(match[1], args);
          emitter('game:action', { ...action, result, done: Date.now() });
          reply({ ok: true, result });
        } catch (e) {
          emitter('game:action', { ...action, error: e.message, done: Date.now() });
          reply({ ok: false, error: e.message });
        }
      });
    });
    control.listen(0, '127.0.0.1', () => {
      setState({ controlUrl: `http://127.0.0.1:${control.address().port}` });
      resolve();
    });
  });
}

async function bootGame() {
  setState({ server: 'starting', error: null });
  await server.start({
    onLine: (l) => emitter('game:log', l),
    log: (text) => emitter('game:log', { line: `[benana] ${text}`, level: 'info', at: Date.now() }),
  });
  setState({ server: 'running' });
  await prepareWorld();
  await startHost();
  await prepareBot();
  setState({ viewerUrl: `http://127.0.0.1:${VIEWER_PORT}` });
}

let booting = null;
async function start(emit = () => {}) {
  emitter = emit;
  if (mock()) return setState({ server: 'running', bot: 'online' });
  if (state.server === 'running' && state.bot === 'online') return status();
  if (!booting) {
    booting = (async () => {
      systemNode();
      await startControl();
      await bootGame();
    })()
      .catch((e) => {
        setState({ server: server.running() ? 'running' : 'error', error: e.message });
        throw e;
      })
      .finally(() => { booting = null; });
  }
  await booting;
  return status();
}

async function stop() {
  demo(false);
  if (mock()) return setState({ server: 'stopped', bot: 'offline' });
  await stopHost();
  await server.stop();
  return setState({ server: 'stopped', bot: 'offline', viewerUrl: null });
}

async function deployPlugin({ jarPath, emit }) {
  if (emit) emitter = emit;
  if (!fs.existsSync(jarPath)) return { loaded: false, plugin: null, errors: [`Jar not found: ${jarPath}`], logTail: [] };
  if (mock()) return { loaded: true, plugin: path.basename(jarPath, '.jar'), errors: [], logTail: ['[mock] plugin enabled'] };
  systemNode();
  await startControl();
  await stopHost();
  await server.stop();
  setState({ server: 'stopped', bot: 'offline', viewerUrl: null });
  const dir = server.pluginsDir();
  fs.mkdirSync(dir, { recursive: true });
  for (const f of fs.readdirSync(dir)) if (/^studio-.*\.jar$/.test(f)) fs.rmSync(path.join(dir, f));
  fs.copyFileSync(jarPath, path.join(dir, `studio-${path.basename(jarPath)}`));
  const since = Date.now();
  await bootGame();
  const lines = server.logSince(since);
  const enabled = lines.map((l) => l.line.match(/\[([^\]]+)\] Enabling (\S+) v/)).find(Boolean);
  const errors = lines.filter((l) => l.level === 'error').map((l) => l.line);
  return { loaded: Boolean(enabled), plugin: enabled ? enabled[2] : null, errors, logTail: lines.slice(-40).map((l) => l.line) };
}

async function runCommand(command) {
  if (mock()) return `[mock] ${command}`;
  return server.command(String(command).replace(/^\//, ''));
}

function mcpConfig({ runId, verdictFile, testPlanFile }) {
  return {
    mcpServers: {
      minecraft: {
        command: 'node',
        args: [MCP],
        env: {
          BENANA_GAME_URL: state.controlUrl || '',
          BENANA_VERDICT_FILE: verdictFile,
          BENANA_TEST_PLAN: testPlanFile,
          BENANA_RUN_ID: String(runId),
        },
      },
    },
  };
}

function playtestPrompt(testPlan) {
  return [
    'You are a Minecraft playtester. You control a real player bot on a local Paper server through the `minecraft` tools.',
    `Mod under test: ${testPlan.modName}: ${testPlan.summary}`,
    'Run `game_setup` with the setup commands, then perform every check like a player would and measure the outcome with tools.',
    '`attack` and `use_item` accept `trackTicks` to record the target right after the action; use it whenever the expected effect is movement.',
    'Each tool call takes 1-8 real seconds. For anything timing-sensitive (cooldowns, combos), summon all targets first and use `attack_sequence`, which hits them a few ticks apart in one call.',
    'Call `report_check` once per check with what you expected, what you observed, and evidence. Check `server_log` for plugin errors.',
    'Finish with `finish`. Do not edit files.',
    '',
    'Test plan:',
    JSON.stringify(testPlan, null, 2),
  ].join('\n');
}

function readVerdict(verdictFile) {
  let v;
  try { v = JSON.parse(fs.readFileSync(verdictFile, 'utf8')); }
  catch (e) { return { version: 1, finished: false, passed: false, checks: [], serverErrors: [], error: `No verdict: ${e.message}` }; }
  const checks = Array.isArray(v.checks) ? v.checks : [];
  const serverErrors = Array.isArray(v.serverErrors) ? v.serverErrors : [];
  const finished = v.finished === true;
  return { ...v, checks, serverErrors, finished, passed: finished && checks.length > 0 && checks.every((c) => c.status === 'pass') && serverErrors.length === 0 };
}

function mockVerdict(testPlan, attempt) {
  const checks = (testPlan.checks || []).map((c, i) => {
    const failing = attempt <= 1 && i === 0;
    return {
      id: c.id,
      status: failing ? 'fail' : 'pass',
      expected: c.expect,
      observed: failing ? '[mock] max upward velocity 0.0; mob took damage but stayed grounded' : '[mock] matched expectation',
      evidence: { samples: [], serverLog: [] },
      ...(failing ? { suspectedCause: '[mock] velocity is overwritten by knockback after the damage event' } : {}),
    };
  });
  return { version: 1, runId: `mock_${attempt}`, finished: true, passed: checks.every((c) => c.status === 'pass'), summary: '[mock verdict]', checks, serverErrors: [] };
}

// Attract mode for recordings: summon a husk in front of the bot and hit it, on repeat.
let demoTimer = null;
async function demoHit() {
  await runTool('game_setup', { commands: ['kill @e[type=husk]', 'give @bot golden_sword', 'summon husk ^ ^ ^3 {PersistenceRequired:1b}'] });
  await runTool('wait_ticks', { ticks: 25 });
  await runTool('equip', { item: 'golden_sword' });
  const husk = (await runTool('nearby_entities', { radius: 8 })).find((e) => e.name === 'husk');
  return husk ? runTool('attack', { entityId: husk.id, trackTicks: 30 }) : null;
}

function demo(on) {
  clearInterval(demoTimer);
  demoTimer = null;
  if (!on) return { demo: false };
  let busy = false;
  const tick = () => {
    if (busy || state.bot !== 'online') return;
    busy = true;
    demoHit().catch(() => {}).finally(() => { busy = false; });
  };
  demoTimer = setInterval(tick, 7000);
  tick();
  return { demo: true };
}

function handlers(emit) {
  emitter = emit;
  if (process.env.BENANA_GAME_AUTOSTART === '1' && !mock()) {
    setTimeout(() => start(emit).then(() => process.env.BENANA_GAME_DEMO === '1' && demo(true)).catch(() => {}), 2000);
  }
  return {
    'game:demo': ({ on }) => demo(on),
    'game:status': () => status(),
    'game:logs': ({ limit } = {}) => server.logSince(0).slice(-Math.min(Number(limit) || 300, 1000)),
    'game:start': () => start(emit),
    'game:stop': () => stop(),
    'game:command': ({ command }) => runCommand(command),
    'game:tool': ({ tool, args }) => runTool(tool, args),
  };
}

module.exports = {
  VERSION, status, start, stop, deployPlugin, runCommand, runTool,
  mcpConfig, playtesterTools, playtestPrompt, readVerdict, mockVerdict, handlers,
};
// Bot host: runs under system Node (>=22, Mineflayer's requirement; Electron's Node is older).
// Owns the Mineflayer bot and the prismarine-viewer server. Electron talks to it over the IPC channel:
//   parent -> { id, tool, args }            child -> { id, ok, result | error }
//   child  -> { event: 'status' | 'chat', ... }
const Module = require('node:module');

// prismarine-viewer's shared entity code requires the native `canvas` package at load time for name tags.
// Only the browser bundle draws them, so the server side gets a stub instead of a native build.
const load = Module._load;
Module._load = function loadWithoutCanvas(request, ...rest) {
  if (request === 'canvas') return { createCanvas: () => { throw new Error('canvas is not available in the bot host'); } };
  return load.call(this, request, ...rest);
};

// Serve the viewer page with a closer camera. The stock page orbits from 28 blocks away, which makes the bot
// and mobs too small to read on a recording. OrbitControls zooms on wheel events, including synthetic ones.
const viewerRoutes = require('prismarine-viewer/lib/common');
const setupRoutes = viewerRoutes.setupRoutes;
const ZOOM_PAGE = require('node:fs')
  .readFileSync(require.resolve('prismarine-viewer/public/index.html'), 'utf8')
  .replace('</body>', `<script>
  setTimeout(function zoom() {
    var c = document.querySelector('canvas');
    if (!c) return setTimeout(zoom, 300);
    var n = 0, t = setInterval(function () {
      c.dispatchEvent(new WheelEvent('wheel', { deltaY: -100, bubbles: true, cancelable: true }));
      if (++n >= 12) clearInterval(t);
    }, 20);
  }, 2500);
</script></body>`);
viewerRoutes.setupRoutes = (app, prefix = '') => {
  app.get(`${prefix}/`, (_req, res) => res.type('html').send(ZOOM_PAGE));
  setupRoutes(app, prefix);
};

const mineflayer = require('mineflayer');
const { pathfinder, Movements, goals } = require('mineflayer-pathfinder');
const { mineflayer: viewer } = require('prismarine-viewer');
const { Vec3 } = require('vec3');

const { MC_PORT, MC_VERSION, BOT_NAME, VIEWER_PORT, VIEWER_FIRST_PERSON } = process.env;

const send = (msg) => process.send && process.send(msg);
const round = (n) => Math.round(n * 1000) / 1000;
const vec = (v) => (v ? [round(v.x), round(v.y), round(v.z)] : null);
const chat = [];
const dead = new Set(); // killed mobs linger ~20 ticks for the death animation

const bot = mineflayer.createBot({ host: '127.0.0.1', port: Number(MC_PORT), username: BOT_NAME, version: MC_VERSION, auth: 'offline' });
bot.loadPlugin(pathfinder);

bot.once('spawn', () => {
  const moves = new Movements(bot);
  moves.canDig = false;
  bot.pathfinder.setMovements(moves);
  viewer(bot, { port: Number(VIEWER_PORT), firstPerson: VIEWER_FIRST_PERSON === '1', viewDistance: 4 });
  // The viewer places its camera on the bot's first `move` event; a bot standing still never sends one.
  setInterval(() => bot.entity && bot.emit('move', bot.entity.position.clone()), 1000);
  send({ event: 'status', bot: 'online' });
});
bot.on('entityDead', (e) => dead.add(e.id));
bot.on('entityGone', (e) => dead.delete(e.id));
bot.on('messagestr', (text, position) => {
  if (position === 'game_info') return;
  chat.push({ text, at: Date.now() });
  if (chat.length > 500) chat.shift();
  send({ event: 'chat', text });
});
bot.on('kicked', (reason) => send({ event: 'status', bot: 'offline', error: `Kicked: ${typeof reason === 'string' ? reason : JSON.stringify(reason)}` }));
bot.on('error', (e) => send({ event: 'status', bot: 'offline', error: e.message }));
bot.on('end', () => {
  send({ event: 'status', bot: 'offline' });
  try { bot.viewer?.close(); } catch {}
  setTimeout(() => process.exit(0), 100);
});

function entity(id) {
  const e = bot.entities[Number(id)];
  if (!e) throw new Error(`No entity with id ${id} is loaded near the bot. Call nearby_entities first.`);
  return e;
}

function describe(e) {
  return {
    id: e.id,
    type: e.type,
    name: e.name || e.username || e.displayName,
    position: vec(e.position),
    velocity: vec(e.velocity),
    distance: round(bot.entity.position.distanceTo(e.position)),
    onGround: e.onGround,
  };
}

function target(args) {
  if (args.entityId != null) return entity(args.entityId).position;
  const p = args.position;
  if (Array.isArray(p) && p.length === 3) return new Vec3(p[0], p[1], p[2]);
  throw new Error('Pass entityId or position [x, y, z].');
}

async function track(e, ticks = 20) {
  const samples = [];
  const start = e.position.clone();
  let prev = e.position.clone();
  for (let tick = 0; tick < Math.min(Number(ticks) || 20, 200); tick++) {
    await bot.waitForTicks(1);
    if (!bot.entities[e.id]) { samples.push({ tick, gone: true }); break; }
    const dp = e.position.minus(prev);
    prev = e.position.clone();
    samples.push({ tick, pos: vec(e.position), vel: vec(e.velocity), dpos: vec(dp) });
  }
  const live = samples.filter((s) => s.pos);
  return {
    entityId: e.id,
    name: e.name,
    // Server velocity packets are exact; position updates arrive batched every few ticks.
    maxUpwardVelocity: round(Math.max(0, ...live.map((s) => s.vel[1]))),
    maxHeightGain: round(Math.max(0, ...live.map((s) => s.pos[1] - start.y))),
    start: vec(start),
    end: live.length ? live[live.length - 1].pos : null,
    samples,
  };
}

const tools = {
  async bot_state() {
    return {
      username: bot.username,
      position: vec(bot.entity.position),
      health: bot.health,
      food: bot.food,
      gameMode: bot.game.gameMode,
      heldItem: bot.heldItem ? { name: bot.heldItem.name, count: bot.heldItem.count } : null,
      inventory: bot.inventory.items().map((i) => ({ name: i.name, count: i.count, slot: i.slot })),
    };
  },
  async nearby_entities({ radius = 16 } = {}) {
    return Object.values(bot.entities)
      .filter((e) => e !== bot.entity && !dead.has(e.id) && e.position.distanceTo(bot.entity.position) <= radius)
      .map(describe)
      .sort((a, b) => a.distance - b.distance);
  },
  async equip({ item }) {
    const found = bot.inventory.items().find((i) => i.name === item || i.name === String(item).replace(/^minecraft:/, ''));
    if (!found) throw new Error(`${item} is not in the inventory.`);
    await bot.equip(found, 'hand');
    return { holding: found.name };
  },
  async look_at(args) {
    const pos = target(args);
    const height = args.entityId != null ? entity(args.entityId).height || 1.6 : 0;
    await bot.lookAt(pos.offset(0, height * 0.8, 0), true);
    return { lookingAt: vec(pos) };
  },
  async move_to(args) {
    const pos = target(args);
    const range = Number(args.range ?? 2);
    const goal = new goals.GoalNear(pos.x, pos.y, pos.z, range);
    await Promise.race([
      bot.pathfinder.goto(goal),
      new Promise((_, rej) => setTimeout(() => { bot.pathfinder.stop(); rej(new Error('move_to timed out after 15s')); }, 15000)),
    ]);
    return { position: vec(bot.entity.position) };
  },
  async attack({ entityId, trackTicks = 0 }) {
    const e = entity(entityId);
    if (e.position.distanceTo(bot.entity.position) > 3.5) await tools.move_to({ entityId, range: 2 });
    await bot.lookAt(e.position.offset(0, (e.height || 1.6) * 0.8, 0), true);
    bot.attack(e);
    return trackTicks ? { attacked: e.id, after: await track(e, trackTicks) } : { attacked: e.id };
  },
  // Hits several entities a few ticks apart in one call. Separate tool calls are 1-8s apart,
  // which is too slow for testing cooldowns and combos.
  async attack_sequence({ entityIds = [], intervalTicks = 4, trackTicks = 20 }) {
    const started = Date.now();
    const tracks = [];
    for (const [i, id] of entityIds.entries()) {
      const e = entity(id);
      if (e.position.distanceTo(bot.entity.position) > 3.5) await tools.move_to({ entityId: id, range: 2 });
      await bot.lookAt(e.position.offset(0, (e.height || 1.6) * 0.8, 0), true);
      bot.attack(e);
      const hitAtMs = Date.now() - started;
      tracks.push(track(e, trackTicks).then((after) => ({ entityId: e.id, hitAtMs, after: { ...after, samples: after.samples.slice(0, 8) } })));
      if (i < entityIds.length - 1) await bot.waitForTicks(Math.max(1, Number(intervalTicks) || 4));
    }
    return { hits: await Promise.all(tracks) };
  },
  async use_item({ entityId, trackTicks = 0 } = {}) {
    if (entityId != null) {
      const e = entity(entityId);
      await bot.lookAt(e.position.offset(0, (e.height || 1.6) * 0.8, 0), true);
      await bot.activateEntity(e);
      return trackTicks ? { used: bot.heldItem?.name, on: e.id, after: await track(e, trackTicks) } : { used: bot.heldItem?.name, on: e.id };
    }
    bot.activateItem();
    await bot.waitForTicks(5);
    bot.deactivateItem();
    return { used: bot.heldItem?.name };
  },
  async track_entity({ entityId, ticks = 20 }) {
    return track(entity(entityId), ticks);
  },
  async wait_ticks({ ticks = 20 } = {}) {
    await bot.waitForTicks(Math.min(Number(ticks) || 20, 400));
    return { waited: ticks };
  },
  async chat({ message }) {
    bot.chat(String(message));
    await bot.waitForTicks(4);
    return { sent: message };
  },
  async read_chat({ sinceMs = 0 } = {}) {
    return chat.filter((c) => c.at >= sinceMs);
  },
};

process.on('message', async ({ id, tool, args }) => {
  try {
    if (!tools[tool]) throw new Error(`Unknown bot tool ${tool}`);
    if (!bot.entity) throw new Error('The bot has not spawned yet.');
    send({ id, ok: true, result: await tools[tool](args || {}) });
  } catch (e) {
    send({ id, ok: false, error: e.message });
  }
});
process.on('disconnect', () => { try { bot.quit(); } catch {} process.exit(0); });

// Mod Studio pipeline: prompt -> spec/test plan -> build -> deploy -> playtest -> fix -> retry.
// Interface with the game runtime: docs/hackathon/CONTRACTS.md.
const fs = require('node:fs');
const path = require('node:path');
const { appRoot, dataDir } = require('../env.cjs');
const game = require('../game/index.cjs');
const neatlogs = require('../neatlogs.cjs');
const repo = require('./repo.cjs');
const prompts = require('./prompts.cjs');
const { runClaude, MODELS } = require('./claude.cjs');

const MAX_ATTEMPTS = 3;
const studioDir = path.join(dataDir, 'studio');
const lessonsFile = path.join(studioDir, 'lessons.json');
const SEEDED = path.join(appRoot, 'fixtures', 'seeded');

const mods = new Map();
let active = null; // { modId, stop }
let emit = () => {};
let log = () => {};

const now = () => Date.now();
const modFile = (id) => path.join(studioDir, id, 'mod.json');

function publicMod(mod) {
  const { feed, ...rest } = mod;
  return { ...rest, feedCount: feed.length, running: active?.modId === mod.id };
}

let saveTimers = new Map();
function save(mod) {
  mod.updatedAt = now();
  emit('studio:mod', publicMod(mod));
  clearTimeout(saveTimers.get(mod.id));
  saveTimers.set(mod.id, setTimeout(() => {
    fs.mkdirSync(path.dirname(modFile(mod.id)), { recursive: true });
    fs.writeFileSync(modFile(mod.id), JSON.stringify(mod, null, 2));
  }, 300));
}

function load() {
  if (!fs.existsSync(studioDir)) return;
  for (const id of fs.readdirSync(studioDir)) {
    try {
      const mod = JSON.parse(fs.readFileSync(modFile(id), 'utf8'));
      if (!['passed', 'failed', 'stopped'].includes(mod.status)) mod.status = 'stopped';
      mods.set(mod.id, mod);
    } catch {}
  }
}

function feed(mod, entry) {
  const item = { at: now(), ...entry };
  mod.feed.push(item);
  if (mod.feed.length > 1500) mod.feed.splice(0, 300);
  emit('studio:feed', { modId: mod.id, item });
}

function setPhase(mod, phase, text) {
  mod.phase = phase;
  if (text) feed(mod, { role: 'benana', kind: 'phase', phase, text });
  save(mod);
}

function lessons() {
  try { return JSON.parse(fs.readFileSync(lessonsFile, 'utf8')); } catch { return []; }
}

function addLesson(lesson, mod) {
  const all = lessons();
  all.push({ lesson, mod: mod.name, at: now() });
  fs.mkdirSync(studioDir, { recursive: true });
  fs.writeFileSync(lessonsFile, JSON.stringify(all.slice(-20), null, 2));
}

function parseJson(text) {
  const fenced = String(text).match(/```(?:json)?\s*([\s\S]*?)```/);
  const raw = fenced ? fenced[1] : String(text).slice(String(text).indexOf('{'), String(text).lastIndexOf('}') + 1);
  return JSON.parse(raw);
}

const slugify = (s) => s.replace(/([a-z])([A-Z])/g, '$1-$2').replace(/[^a-zA-Z0-9]+/g, '-').replace(/^-|-$/g, '').toLowerCase().slice(0, 32);

// Runs one agent session for a mod and records it on the attempt.
async function agent(mod, attempt, role, options) {
  const session = { role, model: options.model, startedAt: now(), sessionId: null };
  if (attempt) attempt.sessions.push(session);
  else mod.sessions.push(session);
  save(mod);
  const handle = runClaude({
    ...options,
    onEvent: (ev) => {
      if (ev.kind === 'session') { session.sessionId = ev.sessionId; save(mod); return; }
      feed(mod, { attempt: attempt?.n ?? 0, role, ...ev, input: undefined });
      if (role === 'playtester' && ev.kind === 'tool') emit('studio:playtester', { modId: mod.id, tool: ev.name, input: ev.input });
    },
  });
  active.stop = handle.stop;
  const result = await handle.done;
  Object.assign(session, { endedAt: now(), ok: result.ok, error: result.error, usage: result.usage, sessionId: result.sessionId || session.sessionId });
  save(mod);
  if (active?.stopped) throw new Error('Stopped by user.');
  return result;
}

async function specPhase(mod) {
  if (mod.seed) {
    const seeded = JSON.parse(fs.readFileSync(path.join(SEEDED, 'spec.json'), 'utf8'));
    feed(mod, { role: 'benana', kind: 'note', text: 'Seeded bug fallback: using the labeled LaunchSword fixture spec instead of the spec agent.' });
    return seeded;
  }
  const work = path.join(studioDir, mod.id, 'spec');
  fs.mkdirSync(work, { recursive: true });
  const res = await agent(mod, null, 'spec', { cwd: work, prompt: prompts.spec(mod.prompt), model: MODELS.build, tools: [] });
  if (!res.ok) throw new Error(`Spec agent failed: ${res.error}`);
  const spec = parseJson(res.final);
  if (!/^[A-Za-z]{2,24}$/.test(spec.modName || '')) spec.modName = 'StudioMod';
  if (!spec.testPlan?.checks?.length) throw new Error('Spec agent returned no test checks.');
  spec.testPlan.modName = spec.modName;
  return spec;
}

async function trace(sessionId) {
  if (!sessionId || !neatlogs.configured()) return '';
  const ev = await neatlogs.evidence({ sessionId });
  if (!ev.matched) return '';
  return ev.traces.map((t) => {
    const spans = (t.spans || []).slice(0, 25).map((s) => `  - ${s.name || s.span_name || 'span'}${s.status === 'error' || s.status_code === 'ERROR' ? ' (error)' : ''}`).join('\n');
    return `trace ${t.traceId || t.trace_id || t.id}\n${spans}`;
  }).join('\n').slice(0, 4000);
}

async function codePhase(mod, attempt, previous) {
  if (attempt.role === 'seeded') {
    fs.copyFileSync(path.join(SEEDED, 'LaunchSword.java'), path.join(mod.repoDir, 'src', 'main', 'java', 'dev', 'benana', 'mod', 'LaunchSword.java'));
    feed(mod, { attempt: attempt.n, role: 'benana', kind: 'note', text: 'Seeded bug fallback: attempt 1 uses the labeled fixture source (velocity set inside the damage event).' });
    return;
  }
  const lessonList = lessons().map((l) => l.lesson);
  if (attempt.role === 'builder') {
    const res = await agent(mod, attempt, 'builder', { cwd: mod.repoDir, prompt: prompts.builder({ mod, lessons: lessonList }), model: MODELS.build, tools: ['Read', 'Edit', 'Write', 'Glob', 'Grep', 'Bash'], allowedTools: ['Read', 'Edit', 'Write', 'Glob', 'Grep', 'Bash'] });
    if (!res.ok) throw new Error(`Builder failed: ${res.error}`);
    attempt.summary = res.final.slice(0, 2000);
    return;
  }
  const cps = await repo.checkpoints(mod.repoDir);
  const context = {
    history: await repo.history(mod.repoDir),
    checkpoints: cps.ok ? cps.items.slice(0, 8).map((c) => `${c.checkpoint_id} "${c.message}" session ${c.session_id} (${c.agent})`).join('\n') : '',
    trace: await trace(previous.sessions.find((s) => s.role === 'playtester')?.sessionId).catch(() => ''),
  };
  attempt.context = { entireCheckpoints: cps.ok ? cps.items.length : 0, neatlogsTrace: Boolean(context.trace) };
  const res = await agent(mod, attempt, 'fixer', { cwd: mod.repoDir, prompt: prompts.fixer({ mod, attempt, previous, context }), model: MODELS.build, tools: ['Read', 'Edit', 'Write', 'Glob', 'Grep', 'Bash'], allowedTools: ['Read', 'Edit', 'Write', 'Glob', 'Grep', 'Bash'] });
  if (!res.ok) throw new Error(`Fixer failed: ${res.error}`);
  attempt.summary = res.final.slice(0, 2000);
  const lesson = res.final.match(/^LESSON:\s*(.+)$/m);
  if (lesson) attempt.lesson = lesson[1].trim();
}

async function playtestPhase(mod, attempt) {
  const dir = path.join(mod.repoDir, 'playtest', `attempt-${attempt.n}`);
  fs.mkdirSync(dir, { recursive: true });
  const verdictFile = path.join(dir, 'verdict.json');
  const testPlanFile = path.join(mod.repoDir, 'playtest', 'test-plan.json');
  fs.rmSync(verdictFile, { force: true });

  if (game.status().mock) {
    const v = game.mockVerdict(mod.testPlan, attempt.n);
    fs.writeFileSync(verdictFile, JSON.stringify(v, null, 2));
    feed(mod, { attempt: attempt.n, role: 'playtester', kind: 'note', text: '[mock runtime] canned verdict' });
    return game.readVerdict(verdictFile);
  }

  for (let run = 1; run <= 2; run++) {
    const mcpFile = path.join(studioDir, mod.id, `mcp-attempt-${attempt.n}.json`);
    fs.mkdirSync(path.dirname(mcpFile), { recursive: true });
    fs.writeFileSync(mcpFile, JSON.stringify(game.mcpConfig({ runId: `${mod.id}_${attempt.n}`, verdictFile, testPlanFile })));
    const poll = setInterval(() => {
      if (!fs.existsSync(verdictFile)) return;
      const live = game.readVerdict(verdictFile);
      attempt.verdict = { ...live, live: true };
      save(mod);
    }, 1000);
    try {
      await agent(mod, attempt, 'playtester', { cwd: mod.repoDir, prompt: game.playtestPrompt(mod.testPlan), model: MODELS.playtest, tools: [], allowedTools: game.playtesterTools, mcpConfigFile: mcpFile });
    } finally {
      clearInterval(poll);
    }
    const verdict = game.readVerdict(verdictFile);
    if (verdict.finished) return verdict;
    feed(mod, { attempt: attempt.n, role: 'benana', kind: 'note', text: run === 1 ? 'The playtester stopped before finishing; running it again.' : 'The playtester did not finish the test plan.' });
  }
  return game.readVerdict(verdictFile);
}

async function runAttempt(mod, n, previous) {
  const attempt = { n, role: n === 1 ? (mod.seed ? 'seeded' : 'builder') : 'fixer', status: 'running', startedAt: now(), sessions: [] };
  mod.attempts.push(attempt);
  save(mod);

  setPhase(mod, n === 1 ? 'build' : 'fix', n === 1 ? `Attempt 1: writing ${mod.name}` : `Attempt ${n}: fixing what the playtester found`);
  await codePhase(mod, attempt, previous);

  setPhase(mod, 'compile', `Attempt ${n}: compiling with Maven`);
  attempt.build = await repo.build(mod.repoDir, mod.name);
  if (!attempt.build.ok) {
    attempt.failure = { kind: 'build', summary: 'The plugin did not compile.' };
    attempt.commit = await repo.commit(mod.repoDir, `Attempt ${n} (${attempt.role}): build failed`);
    return attempt;
  }
  attempt.commit = await repo.commit(mod.repoDir, `Attempt ${n} (${attempt.role}): ${attempt.role === 'fixer' ? 'fix from playtest evidence' : 'implement'} ${mod.name}`);
  feed(mod, { attempt: n, role: 'benana', kind: 'note', text: `Committed ${attempt.commit.sha.slice(0, 7)}${attempt.commit.checkpoint ? `, Entire checkpoint ${attempt.commit.checkpoint}` : ''}` });

  setPhase(mod, 'deploy', `Attempt ${n}: deploying to the Paper server`);
  attempt.deploy = await game.deployPlugin({ jarPath: attempt.build.jar, emit });
  if (!attempt.deploy.loaded) {
    attempt.failure = { kind: 'load', summary: 'The plugin did not load on the server.' };
    return attempt;
  }

  setPhase(mod, 'playtest', `Attempt ${n}: the AI player is testing ${mod.name} in-game`);
  attempt.verdict = await playtestPhase(mod, attempt);
  const tally = attempt.verdict.checks.map((c) => `${c.id}=${c.status}`).join(', ');
  attempt.playtestCommit = await repo.commit(mod.repoDir, `Playtest attempt ${n}: ${attempt.verdict.passed ? 'PASS' : 'FAIL'}${tally ? ` (${tally})` : ''}`);
  if (!attempt.verdict.passed) {
    const failed = attempt.verdict.checks.filter((c) => c.status !== 'pass');
    attempt.failure = attempt.verdict.finished
      ? { kind: 'playtest', summary: failed.length ? failed.map((c) => `${c.id}: ${c.observed}`).join(' · ') : `${attempt.verdict.serverErrors.length} server error(s)` }
      : { kind: 'playtest', summary: attempt.verdict.error || 'The playtester did not finish.' };
  }
  return attempt;
}

async function run(mod) {
  active = { modId: mod.id, stop: () => {}, stopped: false };
  try {
    if (game.status().bot !== 'online' && !game.status().mock) {
      setPhase(mod, 'game', 'Starting the Minecraft server');
      await game.start(emit);
    }
    mod.status = 'running';
    setPhase(mod, 'spec', 'Writing the spec and an in-game test plan');
    const spec = await specPhase(mod);
    mod.name = spec.modName;
    mod.spec = { summary: spec.summary, behavior: spec.behavior || [] };
    mod.testPlan = spec.testPlan;
    feed(mod, { role: 'spec', kind: 'plan', text: `${mod.testPlan.checks.length} checks: ${mod.testPlan.checks.map((c) => c.title).join(' · ')}` });

    setPhase(mod, 'repo', 'Creating the mod repository with Entire and Neatlogs hooks');
    const created = await repo.create({ slug: `${slugify(mod.name)}-${mod.id.slice(-4)}`, name: mod.name, summary: mod.spec.summary });
    mod.repoDir = created.dir;
    mod.partners = created.partners;
    fs.mkdirSync(path.join(mod.repoDir, 'playtest'), { recursive: true });
    fs.writeFileSync(path.join(mod.repoDir, 'playtest', 'test-plan.json'), JSON.stringify(mod.testPlan, null, 2));
    await repo.commit(mod.repoDir, 'Add the in-game test plan');
    save(mod);

    let previous = null;
    for (let n = 1; n <= MAX_ATTEMPTS; n++) {
      const attempt = await runAttempt(mod, n, previous);
      attempt.status = attempt.failure ? 'failed' : 'passed';
      attempt.endedAt = now();
      save(mod);
      if (!attempt.failure) {
        mod.status = 'passed';
        if (attempt.lesson) addLesson(attempt.lesson, mod);
        setPhase(mod, 'done', n === 1 ? `${mod.name} passed every check on the first attempt` : `${mod.name} passed after ${n} attempts`);
        return;
      }
      feed(mod, { attempt: n, role: 'benana', kind: 'failure', text: `Attempt ${n} failed (${attempt.failure.kind}): ${attempt.failure.summary}` });
      previous = attempt;
    }
    mod.status = 'failed';
    setPhase(mod, 'done', `${mod.name} still fails after ${MAX_ATTEMPTS} attempts`);
  } catch (e) {
    mod.status = active?.stopped ? 'stopped' : 'failed';
    mod.error = e.message;
    feed(mod, { role: 'benana', kind: 'error', text: e.message });
    log(`studio: ${e.message}`, 'error');
    save(mod);
  } finally {
    active = null;
    save(mod);
  }
}

function create({ prompt, seed = false }) {
  if (active) throw new Error('Another mod is running. Stop it or wait for it to finish.');
  const text = String(prompt || '').trim();
  if (!seed && text.length < 8) throw new Error('Describe the mod in a sentence.');
  const id = `mod_${now().toString(36)}`;
  const mod = {
    id, prompt: seed ? text || 'A golden sword that launches any mob it hits into the sky with particles, with a 3 second cooldown.' : text,
    seed: Boolean(seed), name: 'New mod', status: 'queued', phase: 'queued', createdAt: now(), updatedAt: now(),
    spec: null, testPlan: null, repoDir: null, partners: null, sessions: [], attempts: [], feed: [], error: null,
  };
  mods.set(id, mod);
  save(mod);
  run(mod);
  return publicMod(mod);
}

function repoOf(id) {
  const mod = mods.get(id);
  if (!mod?.repoDir) throw new Error('This mod has no repository yet.');
  return mod.repoDir;
}

function handlers(deps) {
  emit = deps.emit;
  log = deps.log;
  load();
  return {
    'studio:list': () => [...mods.values()].sort((a, b) => b.createdAt - a.createdAt).map(publicMod),
    'studio:get': ({ id }) => {
      const mod = mods.get(id);
      if (!mod) throw new Error('Unknown mod.');
      return { ...publicMod(mod), feed: mod.feed };
    },
    'studio:create': create,
    'studio:stop': ({ id }) => {
      if (active?.modId !== id) return false;
      active.stopped = true;
      active.stop();
      return true;
    },
    'studio:evidence': ({ sessionId }) => neatlogs.evidence({ sessionId }),
    'studio:checkpoints': async ({ id }) => {
      const mod = mods.get(id);
      return mod?.repoDir ? repo.checkpoints(mod.repoDir) : { ok: false, items: [], error: 'No repository yet.' };
    },
    'studio:files': ({ id }) => repo.files(repoOf(id)),
    'studio:file': ({ id, path: rel }) => repo.readFile(repoOf(id), rel),
    'studio:diff': ({ id, sha }) => repo.diff(repoOf(id), sha),
    'studio:lessons': () => lessons(),
    'studio:partners': async () => ({ neatlogs: await neatlogs.status() }),
  };
}

