import org.bukkit.event.EventPriority;
import org.bukkit.event.Listener;
import org.bukkit.event.entity.EntityShootBowEvent;
import org.bukkit.event.entity.ProjectileHitEvent;
import org.bukkit.event.player.PlayerQuitEvent;
import org.bukkit.persistence.PersistentDataType;
import org.bukkit.plugin.java.JavaPlugin;

public final class ExplosiveArrows extends JavaPlugin implements Listener {
    private static final long COOLDOWN_MS = 5000L;
    private static final float EXPLOSION_POWER = 2.0f;

    private final Map<UUID, Long> cooldownStart = new HashMap<>();
    // Server tick on which each player's cooldown started, so multishot arrows fired together all explode.
    private final Map<UUID, Integer> cooldownTick = new HashMap<>();
    private NamespacedKey explosiveKey;

    @Override
    public void onEnable() {
        explosiveKey = new NamespacedKey(this, "explosive");
        getServer().getPluginManager().registerEvents(this, this);
        getLogger().info("ExplosiveArrows enabled");
    }

    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onShoot(EntityShootBowEvent event) {
        if (!(event.getEntity() instanceof Player player)) {
            return;
        }
        Entity projectile = event.getProjectile();
        if (!(projectile instanceof AbstractArrow arrow) || projectile instanceof Trident) {
            return;
        }

        UUID id = player.getUniqueId();
        long now = System.currentTimeMillis();
        int tick = Bukkit.getCurrentTick();
        Long start = cooldownStart.get(id);
        boolean sameVolley = start != null && cooldownTick.getOrDefault(id, -1) == tick;

        if (start != null && !sameVolley && now - start < COOLDOWN_MS) {
            double remaining = (COOLDOWN_MS - (now - start)) / 1000.0;
            String text = String.format(Locale.US, "%.1f", remaining);
            player.sendMessage("Explosive arrows on cooldown: " + text + "s remaining");
            getLogger().info(player.getName() + " shot a normal arrow (cooldown " + text + "s remaining)");
            return;
        }

        arrow.getPersistentDataContainer().set(explosiveKey, PersistentDataType.BYTE, (byte) 1);
        if (!sameVolley) {
            cooldownStart.put(id, now);
            cooldownTick.put(id, tick);
        }
        getLogger().info(player.getName() + " shot an explosive arrow; cooldown started");
    }

    @EventHandler
    public void onHit(ProjectileHitEvent event) {
        if (!(event.getEntity() instanceof AbstractArrow arrow)) {
            return;
        }
        if (!arrow.getPersistentDataContainer().has(explosiveKey, PersistentDataType.BYTE)) {
            return;
        }
        // Clear the tag first so the arrow can never explode twice.
        arrow.getPersistentDataContainer().remove(explosiveKey);

        Location loc = arrow.getLocation();
        Entity source = arrow.getShooter() instanceof Entity shooter ? shooter : arrow;
        loc.getWorld().createExplosion(loc, EXPLOSION_POWER, false, false, source);
        arrow.remove();

        String target = event.getHitEntity() != null
                ? event.getHitEntity().getType().name()
                : (event.getHitBlock() != null ? event.getHitBlock().getType().name() : "unknown");
        getLogger().info(String.format(Locale.US, "Explosive arrow from %s hit %s at %.1f, %.1f, %.1f",
                source.getName(), target, loc.getX(), loc.getY(), loc.getZ()));
    }

    @EventHandler
    public void onQuit(PlayerQuitEvent event) {
        UUID id = event.getPlayer().getUniqueId();
        cooldownStart.remove(id);
        cooldownTick.remove(id);
    }
